(function(root){
const KEY='radioquest-technician-2026-v1';
const fresh=()=>({version:1,xp:0,streak:0,best:0,stats:{},missed:[],cursor:{},session:null,sound:true,lastFailed:null,missionsDone:0});
function validate(s,questions){const ids=new Set(questions.map(q=>q.id));if(!s||s.version!==1||!s.stats||typeof s.stats!=='object'||!Array.isArray(s.missed)||!s.cursor)throw Error('Not a Radio Quest backup');for(const n of ['xp','streak','best'])if(!Number.isFinite(s[n])||s[n]<0)throw Error('Invalid progress');for(const [id,v]of Object.entries(s.stats))if(!ids.has(id)||!v||!Number.isFinite(v.attempts)||typeof v.correct!=='boolean')throw Error('Invalid answer record');if(s.missed.some(id=>!ids.has(id)))throw Error('Invalid question');s.missionsDone=Number.isFinite(s.missionsDone)&&s.missionsDone>=0?Math.floor(s.missionsDone):0;if(s.session){const a=s.session;if(!Array.isArray(a.ids)||!a.ids.length||a.ids.length>10||a.ids.some(id=>!ids.has(id))||!Number.isInteger(a.index)||a.index<0||a.index>a.ids.length||!Number.isFinite(a.correct)||a.correct<0||!['order','random','retry'].includes(a.mode)||!(a.selected===null||Number.isInteger(a.selected)&&a.selected>=0&&a.selected<=3))throw Error('Invalid mission');}return s;}
function start(s,questions,mode,topic='all',rng=Math.random){let pool=questions.filter(q=>topic==='all'||q.id.startsWith(topic));let ids;if(mode==='retry'){ids=s.missed.filter(id=>pool.some(q=>q.id===id));if(ids.includes(s.lastFailed))ids=[s.lastFailed,...ids.filter(id=>id!==s.lastFailed)];ids=ids.slice(0,10);}else if(mode==='random'){ids=pool.map(q=>q.id);for(let i=ids.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[ids[i],ids[j]]=[ids[j],ids[i]];}ids=ids.slice(0,10);}else{let cursor=s.cursor[topic]||0;if(cursor>=pool.length)cursor=0;ids=pool.slice(cursor,cursor+10).map(q=>q.id);}if(!ids.length)return false;s.session={mode,topic,ids,index:0,selected:null,correct:0,earned:0,streakStart:s.streak};return true;}
function answer(s,questions,choice){const a=s.session;if(!a||a.selected!==null||a.index>=a.ids.length||!Number.isInteger(choice)||choice<0||choice>3)return null;const q=questions.find(q=>q.id===a.ids[a.index]);a.selected=choice;const ok=choice===q.answer;const old=s.stats[q.id];s.stats[q.id]={attempts:(old?.attempts||0)+1,correct:ok};let gain=0;if(ok){s.streak++;s.best=Math.max(s.best,s.streak);gain=10+(s.streak%5===0?15:0);s.xp+=gain;a.earned+=gain;a.correct++;s.missed=s.missed.filter(id=>id!==q.id);}else{s.streak=0;if(!s.missed.includes(q.id))s.missed.push(q.id);s.lastFailed=q.id;}if(a.mode==='order'){const pool=questions.filter(q=>a.topic==='all'||q.id.startsWith(a.topic));s.cursor[a.topic]=pool.findIndex(x=>x.id===q.id)+1;}return {ok,gain,q};}
function next(s){if(!s.session||s.session.selected===null)return false;s.session.index++;s.session.selected=null;if(s.session.index>=s.session.ids.length)s.missionsDone++;return true;}
root.RadioEngine={KEY,fresh,validate,start,answer,next};
})(typeof window!=='undefined'?window:globalThis);
